// Lê do Supabase os produtos ATIVOS do catálogo da fábrica (tabela produtos).
// Saída: um item por produto { tiny_id, codigo, descricao }.
// Code node roda em sandbox: sem URLSearchParams e sem temporizador (erro real de 22/09).
const base = $env.SUPABASE_FABRICA_URL, chave = $env.SUPABASE_FABRICA_KEY;
if (!base || !chave) throw new Error('Faltam SUPABASE_FABRICA_URL/KEY no compose do n8n.');
const linhas = await this.helpers.httpRequest({
  method: 'GET',
  url: base + '/rest/v1/produtos?select=tiny_id,codigo,descricao,classe&situacao=eq.A&order=tiny_id.asc',
  headers: { apikey: chave, Authorization: 'Bearer ' + chave, Range: '0-1999' },
  json: true, timeout: 30000,
});
if (!Array.isArray(linhas) || linhas.length === 0) throw new Error('Nenhum produto ativo em produtos — nada a carregar.');
return linhas.map((p) => ({ json: { tiny_id: Number(p.tiny_id), codigo: p.codigo ?? '', descricao: p.descricao ?? '', classe: p.classe ?? '' } }));

// Monta o aviso no MESMO formato do webhook de lançamentos de estoque, para a
// plataforma ler do mesmo jeito (tipo 'estoque_fabrica' em eventos.payload).
// Diferenças: origem 'carga_inicial' e os campos extras que só a API tem
// (saldoReservado e o saldo por depósito) — guardados crus, nada se perde.
const p = $json.retorno?.produto ?? {};
return { json: {
  tipo: 'estoque_fabrica',
  payload: {
    versao: 'carga-1',
    origem: 'carga_inicial',
    cnpj: '27556613000166',
    tipo: 'estoque',
    dados: {
      idProduto: Number(p.id),
      sku: p.codigo ?? '',
      nome: p.nome ?? '',
      saldo: p.saldo ?? null,
      saldoReservado: p.saldoReservado ?? null,
      depositos: p.depositos ?? [],
    },
  },
} };

// produto.obter.estoque recusou algum produto. Os demais JÁ foram gravados.
// Rodar o workflow de novo é seguro (a leitura mais nova vence).
const falhas = $input.all().map((it) => ({
  erro: it.json?.retorno?.erros ?? it.json?.retorno ?? it.json,
}));
throw new Error('produto.obter.estoque (fábrica) falhou em ' + falhas.length + ' produto(s): ' + JSON.stringify(falhas).slice(0, 1500));
